local entries = WordHunterWoW_EntityDataBySource["multilanguage-classic"].kinds["item"]["enUS"]
entries[236418] = { ["name"] = "Soul of the War Veteran", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the War Veteran:\n\nFor 15 sec after leaving a stance, you can use abilities requiring that stance as if you were still in that stance." }
entries[236419] = { ["name"] = "Soul of the Battle Forecaster", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Battle Forecaster:\n\nFor the first 15 sec after activating a stance, you can gain an additional benefit:\n\nBattle Stance/Gladiator Stance: 5% increased damage done.\n\nBerserker Stance: 5% increased critical strike chance.\n\nDefensive Stance: 5% reduced Physical damage taken." }
entries[236420] = { ["name"] = "Soul of the Bloodseeker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Bloodseeker:\n\nOverpower critical strikes refresh the duration of Rend on your target back to its maximum duration." }
entries[236421] = { ["name"] = "Soul of the Titan", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Titan:\n\nYour Heroic Strike, Slam, and Overpower abilities deal 10 + (5 * Combo Points)% more damage." }
entries[236422] = { ["name"] = "Soul of the Destroyer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Destroyer:\n\nYour Slam hits reset the remaining cooldown on your Mortal Strike, Bloodthirst, and Shield Slam abilities." }
entries[236423] = { ["name"] = "Soul of the Deathbound", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Deathbound:\n\nReduces the cooldown on your Death Wish by 50%." }
entries[236424] = { ["name"] = "Soul of the Sanguinist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Sanguinist:\n\nYou deal 15% increased damage while any nearby enemy is afflicted with both your Rend and your Deep Wounds." }
entries[236425] = { ["name"] = "Soul of the Pristine Blocker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Pristine Blocker:\n\nIncreases the block value of your shield by 30." }
entries[236426] = { ["name"] = "Soul of the Savage", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Savage:\n\nYou gain 1 extra Rage every time you take any damage or deal auto attack damage." }
entries[236427] = { ["name"] = "Soul of Enmity", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Enmity:\n\nIncreases all threat you generate in Defensive Stance by an additional 10% and increases all damage you deal in Gladiator Stance by 4%." }
entries[236428] = { ["name"] = "Soul of the Deflective", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Deflective:\n\nYou gain 10 Rage every time you Parry or one of your attacks is Parried." }
entries[236429] = { ["name"] = "Soul of the Revenger", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Revenger:\n\nRevenge also grants you Flurry, increasing your attack speed by 30% for the next 3 swings." }
entries[236430] = { ["name"] = "Soul of the Incessant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Incessant:\n\nWhen your target Parries an attack, you instantly Retaliate for 200% weapon damage to that target. Retaliate cannot be Dodged, Blocked, or Parried, but can only occur once every 30 sec per target." }
entries[236431] = { ["name"] = "Soul of the Thunderbringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Thunderbringer:\n\nReduces the cooldown on Thunder Clap by 100%." }
entries[236432] = { ["name"] = "Soul of the Sentinel", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Sentinel:\n\nYour Shield Slam deals 100% increased threat and its cooldown is reset if it is Dodged, Parried, or Blocked." }
entries[236433] = { ["name"] = "Soul of the Southpaw", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Southpaw:\n\nReduces the cooldown on your Shield Slam ability by 2 sec." }
entries[236434] = { ["name"] = "Soul of the Gladiator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Gladiator:\n\nReduces the cooldown on your Bloodrage ability by 30 sec while you are in Gladiator Stance." }
entries[236435] = { ["name"] = "Soul of the Aftershock", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warrior\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Aftershock:\n\nReduces the cooldown on Shockwave by 25%." }
entries[236436] = { ["name"] = "Soul of the Avoidant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Avoidant:\n\nFeint also grants Avoidance for 6 sec, reducing all damage taken from area of effect attacks from non-players by 50%." }
entries[236437] = { ["name"] = "Soul of the Toxicologist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Toxicologist:\n\nIncreases the critical strike damage bonus of your Poisons by 100%." }
entries[236438] = { ["name"] = "Soul of the Executioner", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Executioner:\n\nYour finishing moves have a 5% chance per combo point to make your next ability cost no energy." }
entries[236439] = { ["name"] = "Soul of the Opportunist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Opportunist:\n\nYour opening moves have a 100% chance to make your next ability cost no energy." }
entries[236440] = { ["name"] = "Soul of the Butcher", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Butcher:\n\nIncreases damage dealt by your main hand weapon from combo-generating abilities by 20%." }
entries[236441] = { ["name"] = "Soul of the Phantom", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Phantom:\n\nReduces the cooldown on Vanish to 1 min. Cannot be combined with Elusiveness." }
entries[236442] = { ["name"] = "Soul of the Scoundrel", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Scoundrel:\n\nIncreases Mutilate and Saber Slash damage by 20%." }
entries[236443] = { ["name"] = "Soul of the Thrill Seeker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Thrill Seeker:\n\nReduces the cooldown on Adrenaline Rush by 4 min." }
entries[236444] = { ["name"] = "Soul of the Shiv Savant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shiv Savant:\n\nIncreases your chance to get a critical strike with Daggers by 5%." }
entries[236445] = { ["name"] = "Soul of the Stalker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Stalker:\n\nIncreases the critical strike chance of your Ambush ability by 30%." }
entries[236446] = { ["name"] = "Soul of the Efficient", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Efficient:\n\nYour finishing moves cost 50% less Energy." }
entries[236447] = { ["name"] = "Soul of the Knife Juggler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Knife Juggler:\n\nWhile Just a Flesh Wound and Blade Dance are active, Crimson Tempest, Blunderbuss, and Fan of Knives cost 20 less Energy and generate 100% increased threat." }
entries[236448] = { ["name"] = "Soul of the Shadow Master", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shadow Master:\n\nVanish now reduces all Magic damage you take by 50% for its duration, but it no longer grants Stealth or breaks movement impairing effects." }
entries[236449] = { ["name"] = "Soul of the Equilibrist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Equilibrist:\n\nYour finishing moves have a 20% chance per combo point to make you take 20% less Physical damage from the next melee attack that hits you within 10 sec." }
entries[236450] = { ["name"] = "Soul of the Poised Brawler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Poised Brawler:\n\nYour Rolling with the Punches now also activates every time you gain a combo point." }
entries[236451] = { ["name"] = "Soul of the Black Belt", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Black Belt:\n\nYour Rolling with the Punches also grants you 20% increased Armor from items per stack (capped at 100%)." }
entries[236452] = { ["name"] = "Soul of the Fencer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Fencer:\n\nThe cooldown on your Main Gauche resets every time your target Dodges or Parries." }
entries[236453] = { ["name"] = "Soul of the Swashbuckler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Swashbuckler:\n\nYour Main Gauche now strikes 1 additional nearby target and also causes your Sinister Strike to strike 1 additional nearby target for 10 sec. These additional strikes are not duplicated by Blade Flurry." }
entries[236454] = { ["name"] = "Soul of the Bloodthirsty", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Rogue\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Bloodthirsty:\n\nWhile active, your Main Gauche also causes you to heal for 15% of all damage done by Sinister Strike. Any excess healing becomes a Blood Barrier, absorbing damage up to 20% of your maximum health." }
entries[236455] = { ["name"] = "Soul of the Transfusionist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Transfusionist:\n\nLifetap generates 50% more mana and 100% less threat." }
entries[236456] = { ["name"] = "Soul of the Refined", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[236457] = { ["name"] = "Soul of the Decimator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Decimator:\n\nYour Nightfall talent has a 4% increased chance to trigger. Your Incinerate has a 4% chance to trigger your Decimation regardless of the target's health." }
entries[236458] = { ["name"] = "Soul of the Rotbringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Rotbringer:\n\nIncreases the damage of your periodic spells and Felguard pet by 10 + (5 * Combo Points)%." }
entries[236459] = { ["name"] = "Soul of the Malevolent", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Malevolent:\n\nPeriodic damage from your Shadowflame, Unstable Affliction, and Curse of Agony spells and damage done by your Felguard have a 4% chance to grant the Shadow Trance effect." }
entries[236460] = { ["name"] = "Soul of the Shadowmancer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shadowmancer:\n\nShadowbolt deals 10 + (5 * Combo Points)% increased damage for each of your effects afflicting the target, up to a maximum of 30 + (5 * Combo Points)%." }
entries[236461] = { ["name"] = "Soul of the Chaos Harbinger", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Chaos Harbinger:\n\nReduces the cooldown on your Chaos Bolt by 50% and increases Chaos Bolt and Shadow Bolt damage done by 10%. In addition, Chaos Bolt can now trigger your Improved Shadow Bolt talent and causes it to have 26 additional charges (does not stack with Shadowflame's additional charges)." }
entries[236462] = { ["name"] = "Soul of the Arsonist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Arsonist:\n\nEach time you hit a target with Conflagrate, you gain 5% increased Fire damage for 20 sec, stacking up to 2 times." }
entries[236463] = { ["name"] = "Soul of the Infernal Shepherd", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Infernal Shepherd:\n\nIncreases the Attack Power and Spell Damage your Demon pet gains from your attributes by 20%." }
entries[236464] = { ["name"] = "Soul of the Demonlord", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Demonlord:\n\nIncreases the benefits of your Master Demonologist talent by 50%." }
entries[236465] = { ["name"] = "Soul of the Demonic Exorcist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Demonic Exorcist:\n\nBanish is now instant cast, and can be cast on yourself while you are a Demon. You cannot Banish yourself while you have Forbearance, and doing so will give you Forbearance for 1 min." }
entries[236466] = { ["name"] = "Soul of the Pained", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Pained:\n\nEach time you take damage, you and your pet gain mana equal to the damage taken, up to a maximum of 420 mana per event. Can only occur once every few seconds." }
entries[236467] = { ["name"] = "Soul of the Flamewraith", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Flamewraith:\n\nYour Shadow Cleave hits have a 20% chance to grant you a Soul Shard, reset the cooldown on Soul Fire, and make your next Soul Fire within 10 sec instant." }
entries[236468] = { ["name"] = "Soul of the Fleshfeaster", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Fleshfeaster:\n\nWhile you are targeting an enemy within 30 yards, Life Tap grants you mana at the expense of your target's health but deals 50 + (5 * Combo Points)% reduced damage to them. Mana gained remains unchanged." }
entries[236469] = { ["name"] = "Soul of the Abyssal", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Abyssal:\n\nWhile Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for 15% of your maximum health when you damage a target with Shadowburn." }
entries[236470] = { ["name"] = "Soul of the Voidborne", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Voidborne:\n\nAny excess healing you deal to yourself is converted into a shield that absorbs damage. This shield can absorb up to 30 + (5 * Combo Points)% of your maximum health, and stacks from multiple heals." }
entries[236471] = { ["name"] = "Soul of the Umbral Blade", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Umbral Blade:\n\nReduces the cooldown on your Shadow Cleave by 1.5 sec." }
entries[236472] = { ["name"] = "Soul of the Ritualist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ritualist:\n\nThe effects of your Demonic Sacrifice now persist while you have a Demon pet active, as long as you do not resummon the sacrificed pet. You may have only one Demonic Sacrifice effect active at a time." }
entries[236473] = { ["name"] = "Soul of the Pain Spreader", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Warlock\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Pain Spreader:\n\nFor 6 sec after using Shadowcleave, your Searing Pain strikes 1 additional target within melee range." }
entries[236474] = { ["name"] = "Soul of the Misleader", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Misleader:\n\nYou generate 100% more threat for 8 sec after using Distracting Shot." }
entries[236475] = { ["name"] = "Soul of the Preyseeker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Preyseeker:\n\nWhile tracking a creature type, you deal 3% increased damage to that creature type." }
