entries[236478] = { ["name"] = "Soul of the Alternator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Alternator:\n\nYour damaging Shot abilities deal 10% increased damage if the previous damaging Shot used was different than the current one." }
entries[236479] = { ["name"] = "Soul of the Toxinologist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Toxinologist:\n\nYour Serpent Sting damage is increased by 25% of your Attack Power over its normal duration." }
entries[236480] = { ["name"] = "Soul of the Bounty Hunter", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Bounty Hunter:\n\nIncreases Kill Shot's damage against non-player controlled targets by 10%." }
entries[236481] = { ["name"] = "Soul of the Trick Shooter", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Trick Shooter:\n\nKill Shot's cooldown is reduced by 50%. While Rapid Fire is active with Rapid Killing engraved, Kill Shot has no cooldown, and when used against a non-player controlled target, fires 3 additional Kill Shots at 30% damage, with a minimum range." }
entries[236482] = { ["name"] = "Soul of the Beast Tender", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Beast Tender:\n\nIncreases the Attack Power your Beast pet gains from your attributes by 20%." }
entries[236483] = { ["name"] = "Soul of the Hound Master", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Hound Master:\n\nIncreases the Focus regeneration of your Beast pet by 20%." }
entries[236484] = { ["name"] = "Soul of the Alpha Tamer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Alpha Tamer:\n\nIncreases the Focus regeneration of your pets by 100%." }
