entries[236487] = { ["name"] = "Soul of the Retaliator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Retaliator:\n\nMongoose Bite also activates for 5 sec whenever your target Parries or Blocks or when your melee attack misses." }
entries[236488] = { ["name"] = "Soul of Echoes", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Echoes:\n\nRaptor Strike increases the damage done by your next other melee ability (excluding Wing Clip) within 5 sec by 20%." }
entries[236489] = { ["name"] = "Soul of the Lethal Lasher", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lethal Lasher:\n\nIncreases damage dealt by your main hand weapon with Raptor Strike and Wyvern Strike by 20%." }
entries[236490] = { ["name"] = "Soul of the Kineticist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Kineticist:\n\nYour periodic damage has a 5% chance to reset the cooldown on one of your Strike abilities. The Strike with the longest remaining cooldown is always chosen." }
entries[236491] = { ["name"] = "Soul of the Strategist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Strategist:\n\nIncreases Wyvern Strike damage over time by 50% and increases your pet's maximum focus by 50." }
entries[236492] = { ["name"] = "Soul of the Deadly Striker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Hunter\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Deadly Striker:\n\nIncreases the impact damage of Mongoose Bite and all Strikes by 20%." }
