entries[236494] = { ["name"] = "Soul of the Refined", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[236495] = { ["name"] = "Soul of the Celebrant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Celebrant:\n\nIncreases your critical strike chance with Prayer of Healing and Circle of Healing by 25%." }
entries[236496] = { ["name"] = "Soul of the Faithful", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Faithful:\n\nAllows 15% of your Mana regeneration to continue while casting." }
entries[236497] = { ["name"] = "Soul of the Serendipitous", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Serendipitous:\n\nYour periodic healing has a 2% chance to make your next spell with a casting time less than 10 seconds an instant cast spell." }
entries[236498] = { ["name"] = "Soul of the Resonant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Resonant:\n\nCircle of Healing and Penance also place a heal over time effect on their targets that heals for 25% as much over 15 sec." }
entries[236499] = { ["name"] = "Soul of the Devotee", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Devotee:\n\nYour Prayer of Mending gains 2 additional charges." }
entries[236500] = { ["name"] = "Soul of the Archbishop", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Archbishop:\n\nYour Circle of Healing now heals the most injured member of the target party for 100% more." }
entries[236501] = { ["name"] = "Soul of the Penitent", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Penitent:\n\nReduces the cooldown of your Penance spell by 6 sec." }
entries[236502] = { ["name"] = "Soul of the Soul Warder", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Soul Warder:\n\nIncreases the damage absorbed by your Power Word: Shield spell by 10%." }
entries[236503] = { ["name"] = "Soul of the Twilight Walker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Twilight Walker:\n\nYou may cast Flash Heal while in Shadowform." }
entries[236504] = { ["name"] = "Soul of the Mind Breaker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Mind Breaker:\n\nMind Blast critical strikes reduce the duration of your next Mind Flay by 50% while increasing its total damage by 25%." }
entries[236505] = { ["name"] = "Soul of the Deathdealer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Deathdealer:\n\nReduces the cooldown of your Shadow Word: Death spell by 6 sec." }
entries[236506] = { ["name"] = "Soul of the Spirit Font", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spirit Font:\n\nYour Shadow Word: Pain has a 2.0% chance per talent point in Spirit Tap to trigger your Spirit Tap talent when it deals damage, or a 20% chance per talent point when a target dies with your Shadow Word: Pain active. Inner Focus also has a 20% chance per talent point to trigger Spirit Tap." }
entries[236507] = { ["name"] = "Soul of the Zealot", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Zealot:\n\nWhile Spirit Tap is active, you deal 25% more Shadow damage." }
entries[236508] = { ["name"] = "Soul of the Unwavering Defiler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Unwavering Defiler:\n\nYour Mind Flay no longer loses duration from taking damage and launches a free Mind Spike at the target on cast." }
entries[236509] = { ["name"] = "Soul of the Contemnor", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Contemnor:\n\nYour Mind Spike is now instant, deals 10% more damage, and can be cast while channeling another spell." }
entries[236510] = { ["name"] = "Soul of the Plaguebringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Priest\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Plaguebringer:\n\nYour Pain and Suffering rune can now refresh the duration of Devouring Plague." }
entries[236511] = { ["name"] = "Soul of the Reverberant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Reverberant:\n\nYour Temporal Beacons last 20% longer." }
entries[236512] = { ["name"] = "Soul of the Chronohealer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Chronohealer:\n\nIncreases all chronomantic healing you deal by 10%." }
entries[236513] = { ["name"] = "Soul of Temporal Longing", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Temporal Longing:\n\nEach time you heal a target with Regeneration, the remaining cooldown on Rewind Time is reduced by 1 sec." }
entries[236514] = { ["name"] = "Soul of the Precognitive", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Precognitive:\n\nYour Arcane Missiles refunds 10% of its base mana cost each time it deals damage." }
entries[236515] = { ["name"] = "Soul of the Arcanist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Arcanist:\n\nArcane Blast gains a 10% additional chance to trigger Missile Barrage, and Missile Barrage now affects Regeneration the same way it affects Arcane Missiles." }
entries[236516] = { ["name"] = "Soul of the Eternal Caretaker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Eternal Caretaker:\n\nYour Temporal Beacons caused by Mass Regeneration now last 21 sec." }
entries[236517] = { ["name"] = "Soul of the Spellbider", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spellbider:\n\nYour Arcane Blast increases damage done by an additional 10% per stack." }
entries[236518] = { ["name"] = "Soul of the Wardshaper", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Wardshaper:\n\nYour Mana Shield, Fire Ward, and Frost Ward absorb 50% more damage and also place a Temporal Beacon on the target for 30 sec." }
entries[236519] = { ["name"] = "Soul of Winter's Grasp", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Winter's Grasp:\n\nIncreases the chance to trigger your Fingers of Frost rune by an additional 15%." }
entries[236520] = { ["name"] = "Soul of the Cryomancer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Cryomancer:\n\nIncreases damage done by your Frostbolt and Spellfrost Bolt spells by 75%." }
entries[236521] = { ["name"] = "Soul of the Evoker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Evoker:\n\nYou are immune to all damage while channeling Evocation." }
entries[236522] = { ["name"] = "Soul of the Elementalist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Elementalist:\n\nYou gain 1% increased damage for 15 sec each time you cast a spell from a different school of magic." }
entries[236523] = { ["name"] = "Soul of the Magical Armorer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Magical Armorer:\n\nMage Armor increases your mana regeneration while casting by an additional 15%. Molten Armor increases your spell damage and healing by 18. Ice Armor grants 20% increased chance to trigger Fingers of Frost." }
entries[236524] = { ["name"] = "Soul of the Kindler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Kindler:\n\nDecreases the threat generated by your Fire spells by 20%." }
entries[236525] = { ["name"] = "Soul of Fiery Convergence", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Fiery Convergence:\n\nYour Pyroblast deals 20% increased damage to targets afflicted with your Fireball's periodic effect." }
entries[236526] = { ["name"] = "Soul of the Perpetual Blaze", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Perpetual Blaze:\n\nYour Fireball's periodic effect gains increased damage over its duration equal to 100% of its impact damage." }
entries[236527] = { ["name"] = "Soul of the Pyromaniac", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Pyromaniac:\n\nYour Fire Blast now also causes your next Fire spell to gain 50% increased critical strike chance for 10 sec." }
entries[236528] = { ["name"] = "Soul of the Igniter", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Igniter:\n\nIncreases the damage done by your Ignite talent by 10%." }
entries[236529] = { ["name"] = "Soul of the Torcher", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Mage\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Torcher:\n\nYour Fireball, Frostfire Bolt, and Balefire Bolt spells gain 4% increased damage for each of your Fire effects on your target, up to a maximum increased of 12%." }
entries[236530] = { ["name"] = "Soul of the Pristine Blocker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Pristine Blocker:\n\nIncreases the block value of your shield by 30." }
entries[236531] = { ["name"] = "Soul of the Lightwarden", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lightwarden:\n\nHeal for 189 to 211 when you Block. Can only heal once every few seconds." }
entries[236532] = { ["name"] = "Soul of the Radiant Defender", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Radiant Defender:\n\nHoly Shield no longer has charges and instead always lasts its full duration. In addition, its damage is increased by 80% of your shield block value." }
entries[236533] = { ["name"] = "Soul of the Shieldbearer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shieldbearer:\n\nIncreases the bonus chance to Block from Holy Shield by 10%." }
entries[236534] = { ["name"] = "Soul of the Bastion", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Bastion:\n\nYou take 10% reduced damage while Holy Shield is active." }
entries[236535] = { ["name"] = "Soul of the Reckoner", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Reckoner:\n\nYour Reckoning talent now has a 20% chance per talent point to trigger when you Block." }
entries[236536] = { ["name"] = "Soul of the Ironclad", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ironclad:\n\nYour Blessing of Sanctuary also grants 10% increase to all stats when cast on yourself." }
entries[236537] = { ["name"] = "Soul of the Guardian", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Guardian:\n\nShield of the Righteous causes your next Holy Light to be instant cast. If cast on self, it will refund 100% of its mana cost and be unaffected by Guarded by the Light." }
entries[236538] = { ["name"] = "Soul of the Peacekeeper", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Peacekeeper:\n\nIncreases the chance for allies to trigger your Judgement of Light or Judgement of Wisdom to 70%." }
entries[236539] = { ["name"] = "Soul of the Refined", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[236540] = { ["name"] = "Soul of the Exemplar", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Exemplar:\n\nWhenever your Flash of Light, Holy Light, or Beacon of Light heals a target to full health, you also heal all members of their party for 189 to 211 health." }
entries[236541] = { ["name"] = "Soul of the Inquisitor", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Inquisitor:\n\nIncreases the critical strike chance of Holy Shock by 5%." }
entries[236542] = { ["name"] = "Soul of the Sovereign", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Sovereign:\n\nIncreases the damage done by your Consecration by 50%." }
entries[236543] = { ["name"] = "Soul of the Dominus", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Dominus:\n\nWhile you are not your Beacon of Light target, your Beacon of Light target is also healed by 75% of the damage you deal with Consecration, Exorcism, Holy Shock, Holy Wrath, and Hammer of Wrath." }
entries[236544] = { ["name"] = "Soul of the Vindicator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Vindicator:\n\nReduces the cooldown on Divine Light by 25%." }
entries[236545] = { ["name"] = "Soul of the Altruist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Altruist:\n\nYour heals on your Beacon of Light target also heal the nearest friendly injured target for 90% as much." }
entries[236546] = { ["name"] = "Soul of the Arbiter", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Arbiter:\n\nYour Judgement of Light and Judgement of Wisdom also grant the effects of Judgement of the Crusader." }
entries[236547] = { ["name"] = "Soul of the Sealbearer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Sealbearer:\n\nYour Seal of Command, Seal of Righteousness, Seal of Martyrdom, and Sunlight deal 35% less damage, but now persist for 6 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active." }
entries[236548] = { ["name"] = "Soul of the Justicar", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Justicar:\n\nIncreases damage done by your damaging Judgements by 5% and your Judgements no longer consume your Seals on the target. Your Judgements can now trigger multiple Seals if active." }
entries[236549] = { ["name"] = "Soul of the Judicator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Judicator:\n\nReduces the cooldown on your Judgement ability by 5 sec, but reduces the damage your Judgements deal by 45%." }
entries[236550] = { ["name"] = "Soul of the Ascendant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ascendant:\n\nYour Judgement grants 1% increased Holy damage for 8 sec, stacking up to 5 times." }
entries[236551] = { ["name"] = "Soul of the Retributor", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Retributor:\n\nIncreases Crusader Strike damage by 150%." }
entries[236552] = { ["name"] = "Soul of the Excommunicator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Excommunicator:\n\nYour basic attacks with two-handed melee weapons increase the damage of your next Exorcism cast within 20 sec by 35%. Stacking up to 3 times." }
entries[236553] = { ["name"] = "Soul of the Lightbringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lightbringer:\n\nIncreases damage done by your Holy Shock spell by 50%." }
entries[236554] = { ["name"] = "Soul of the Exile", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Exile:\n\nReduces the cooldown of your Exorcism spell by 3 sec and increases its damage done by 75%." }
entries[236555] = { ["name"] = "Soul of the Templar", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Paladin\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Templar:\n\nWhile a one-handed weapon is equipped, Crusader Strike now unleashes the Judgement effect of your Seals, but does not consume the Seal." }
entries[236556] = { ["name"] = "Soul of the Windwalker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Windwalker:\n\nIncreases your attack speed by 30% for your next 3 swings after you parry, dodge, or block." }
entries[236557] = { ["name"] = "Soul of the Shield Master", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shield Master:\n\nYour parries and dodges also activate your Shield Mastery rune ability." }
entries[236558] = { ["name"] = "Soul of the Totemic Protector", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Totemic Protector:\n\nYour Stoneskin Totem also reduces Physical damage taken by 5% and your Windwall Totem also reduces Magical damage taken by 5%." }
entries[236559] = { ["name"] = "Soul of the Shock-Absorber", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shock-Absorber:\n\nYour Flame Shock also grants 30% increased chance to Block for 5 sec or until you Block an attack." }
entries[236560] = { ["name"] = "Soul of the Spiritual Bulwark", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spiritual Bulwark:\n\nEach time you Block, your Block amount is increased by 10% of your Spell Damage for 6 sec, stacking up to 3 times." }
entries[236561] = { ["name"] = "Soul of the Maelstrombringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Maelstrombringer:\n\nEach time you Block an attack, you have a 50% chance to trigger your Maelstrom Weapon rune." }
entries[236562] = { ["name"] = "Soul of the Lavawalker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lavawalker:\n\nDamaging a target with Stormstrike, Lava Burst, or Molten Blast also reduces all damage you take by 10% for 10 sec." }
entries[236563] = { ["name"] = "Soul of the True Alpha", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the True Alpha:\n\nWhen your Spirit of the Alpha is cast on yourself, it also increases your health by 5%, your threat generated by 25%, and all damage you deal by 5%." }
entries[236564] = { ["name"] = "Soul of the Totemkeeper", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Totemkeeper:\n\nThe radius of your totems that affect friendly targets is increased to 40 yd." }
entries[236565] = { ["name"] = "Soul of the Ancestors", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ancestors:\n\nAfter casting your Healing Wave, Lesser Healing Wave, or Riptide spell, gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell." }
entries[236566] = { ["name"] = "Soul of the Spiritweaver", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spiritweaver:\n\nYour Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 60%, and the spell will jump to up to 2 additional targets." }
entries[236567] = { ["name"] = "Soul of the Waterwalker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Waterwalker:\n\nYour non-periodic damaging and healing critical strikes now have a 100% chance to trigger your Water Shield, but do not consume a charge or trigger its cooldown." }
entries[236568] = { ["name"] = "Soul of the Stormtender", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Stormtender:\n\nYour Chain Lightning now also heals the target of your most recent Earth Shield for 100% of the damage done." }
entries[236569] = { ["name"] = "Soul of the Elemental Seer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Elemental Seer:\n\nIncreases the healing of Chain Heal and the damage of Chain Lightning by 20%." }
entries[236570] = { ["name"] = "Soul of the Vitalist", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Vitalist:\n\nYour Riptide increases the amount healed by Chain Heal by an additional 25%." }
entries[236571] = { ["name"] = "Soul of the Spirithealer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spirithealer:\n\nReduces the cast time of Chain Heal by 0.5 sec." }
entries[236572] = { ["name"] = "Soul of the Refined", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Refined:\n\nIncreases your critical strike chance with spells and attacks by 2%." }
entries[236573] = { ["name"] = "Soul of the Chieftain", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Chieftain:\n\nYour Flurry talent grants an additional 10% increase to your attack speed." }
entries[236574] = { ["name"] = "Soul of the Furycharged", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Furycharged:\n\nYour chance to trigger Static Shock is increased by 12% (6% while dual - wielding)." }
entries[236575] = { ["name"] = "Soul of the Stormbreaker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Stormbreaker:\n\nIncreases the main hand damage done by your Stormstrike by 50%." }
entries[236576] = { ["name"] = "Soul of the Tempest", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Tempest:\n\nWhile Static Shock is engraved, your Lightning Shield now gains a charge each time you hit a target with Lightning Bolt or Chain Lightning, up to a maximum of 9 charges. In addition, while Static Shock is engraved, your Lightning Shield can now deal critical damage." }
entries[236577] = { ["name"] = "Soul of the Seismic Smasher", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Seismic Smasher:\n\nIncreases Stormstrike and Lava Lash damage by 50%. This effect is increased to 100% if using a two-handed weapon." }
entries[236578] = { ["name"] = "Soul of the Flamebringer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Flamebringer:\n\nYour Stormstrike, Lava Lash and Lava Burst critical strikes cause your target to burn for 30% of the damage done over 4 sec." }
entries[236579] = { ["name"] = "Soul of the Volcano", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Volcano:\n\nYour Lightning Bolt critical strikes have a 35% chance to reset the cooldown on Lava Burst and Chain Lightning and make the next Lava Burst or Chain Lightning within 10 sec instant." }
entries[236580] = { ["name"] = "Soul of the Raging Flame", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Raging Flame:\n\nLava Burst now also refreshes the duration of Flame Shock on your target back to 12 sec." }
entries[236581] = { ["name"] = "Soul of the Elemental Master", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Elemental Master:\n\nYour spell critical strikes now have a 100% chance trigger your Elemental Focus talent." }
entries[236582] = { ["name"] = "Soul of the Tribesman", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Tribesman:\n\nLoyal Beta from your Spirit of the Alpha ability now also increases Fire, Frost, and Nature damage by 5 + (5 * Combo Points)%." }
entries[236583] = { ["name"] = "Soul of the Spirit Guide", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Spirit Guide:\n\nWhile Clearcasting is active, you deal 15 + (5 * Combo Points)% more non-Physical damage." }
entries[236584] = { ["name"] = "Soul of the Elder", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Elder:\n\nYou have a 70% chance to avoid interruption caused by damage while casting Lightning Bolt, Chain Lightning, or Lava Burst, and a 10% increased chance to trigger your Elemental Focus talent." }
entries[236585] = { ["name"] = "Soul of the Elements", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Elements:\n\nIncreases the critical strike damage bonus of your Fire, Frost, and Nature spells by 60%." }
entries[236586] = { ["name"] = "Soul of the Lava Sage", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lava Sage:\n\nYour Lava Burst damage is increased by a percentage equal to your spell critical strike chance." }
entries[236587] = { ["name"] = "Soul of the Ancestral Warden", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ancestral Warden:\n\nIncreases your chance to block attacks with a shield by 10%." }
entries[236588] = { ["name"] = "Soul of the Corrupt", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Shaman\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Corrupt:\n\nIncreases the chance to trigger your Power Surge rune by an additional 5%." }
entries[236589] = { ["name"] = "Soul of the Gentle Paw", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Gentle Paw:\n\nYou may cast Rebirth and Innervate while in Bear Form or Dire Bear Form." }
entries[236590] = { ["name"] = "Soul of the Ferocious", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ferocious:\n\nReduces the cooldown of Enrage by 30 sec and it no longer reduces your armor." }
entries[236591] = { ["name"] = "Soul of the Shifter", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Shifter:\n\nBear Form and Dire Bear Form increase all threat you generate by an additional 20%, and Cower now removes all your threat against the target but has a 20 sec longer cooldown." }
entries[236592] = { ["name"] = "Soul of the Territorial", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Territorial:\n\nSwipe(Bear) also causes your Maul to hit 1 additional target for the next 6 sec." }
entries[236593] = { ["name"] = "Soul of the Beast", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Beast:\n\nYour Mangle(Bear), Swipe(Bear), Maul, and Lacerate abilities gain 5% increased critical strike chance against targets afflicted by your Lacerate." }
entries[236594] = { ["name"] = "Soul of the Lacerator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lacerator:\n\nYour Swipe now spreads your Lacerate from your primary target to other targets it strikes." }
entries[236595] = { ["name"] = "Soul of the Furious", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Furious:\n\nEach time you Dodge while in Dire Bear Form, you gain 10% increased damage on your next Mangle or Swipe, stacking up to 5 times." }
entries[236596] = { ["name"] = "Soul of the Mangler", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Mangler:\n\nReduces the cooldown on Mangle (Bear) by 1.5 sec." }
entries[236597] = { ["name"] = "Soul of the Innervator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Innervator:\n\nWhen you cast Innervate on another player, it is also cast on you." }
entries[236598] = { ["name"] = "Soul of the Nurturer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Nurturer:\n\nCasting your Healing Touch or Nourish spells gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell." }
entries[236599] = { ["name"] = "Soul of the Tranquil", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Tranquil:\n\nReduces the cooldown on Tranquility by 100% and increases its healing by 100%." }
entries[236600] = { ["name"] = "Soul of the Dreamwalker", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Dreamwalker:\n\nYour healing spell critical strikes trigger the Dreamstate effect, granting you 50% of your mana regeneration while casting for 8 sec." }
entries[236601] = { ["name"] = "Soul of the Grove Tender", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Grove Tender:\n\nYour non-periodic spell critical strikes reduce the casting time of your next Healing Touch, Regrowth, or Nourish spell by 0.5 sec." }
entries[236602] = { ["name"] = "Soul of the Feathered Sage", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Feathered Sage:\n\nIncreases healing from Wild Growth by 10%. In addition, Wild Growth can now be used in Moonkin Form, and its healing is increased by an additional 50% in that form." }
entries[236603] = { ["name"] = "Soul of the Benevolent Seer", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Benevolent Seer:\n\nReduces the cooldown of your Rebirth and Innervate spells by 65%." }
entries[236604] = { ["name"] = "Soul of the Lifeweaver", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lifeweaver:\n\nYour critical heals with Healing Touch, Regrowth, and Nourish instantly heal the target for another 50% of the healing they dealt." }
entries[236605] = { ["name"] = "Soul of the Illuminator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Illuminator:\n\nYour Faerie Fire (Feral) also increases the chance for all attacks to hit that target by 1% for 40 sec." }
entries[236606] = { ["name"] = "Soul of Predatory Instincts", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Predatory Instincts:\n\nPeriodic damage from your Rake and Rip can now be critical strikes." }
entries[236607] = { ["name"] = "Soul of the Ripper", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Ripper:\n\nYour Rip and Ferocious Bite have a 20% chance per combo point spent to refresh the duration of Savage Roar back to its initial value." }
entries[236608] = { ["name"] = "Soul of the Claw", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Claw:\n\nIncreases the duration of Rake by 3 sec and its periodic damage by 10%." }
entries[236609] = { ["name"] = "Soul of the Prideful", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Prideful:\n\nYour critical strike chance is increased by 15% while Tiger's Fury is active." }
entries[236610] = { ["name"] = "Soul of the Barbaric", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Barbaric:\n\nYour Shred, Ferocious Bite, and Mangle(Cat) abilities deal 10% increased damage per your Bleed effect on the target, up to a maximum of 20% increase." }
entries[236611] = { ["name"] = "Soul of the Frenetic", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Frenetic:\n\nYour Shred no longer has a positional requirement, but deals 5% more damage if you are behind the target." }
entries[236612] = { ["name"] = "Soul of the Exsanguinator", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Exsanguinator:\n\nYour Mangle, Shred, and Ferocious Bite critical strikes cause your target to Bleed for 30% of the damage done over the next 4 sec sec." }
entries[236613] = { ["name"] = "Soul of the Thornkeeper", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Thornkeeper:\n\nDamage dealt by Thorns increased by 100% and duration increased by 200%." }
entries[236614] = { ["name"] = "Soul of the Lunatic", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Lunatic:\n\nIncreases your chance to hit with spells and attacks by 3%." }
entries[236615] = { ["name"] = "Soul of the Starcaller", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Starcaller:\n\nReduces the cooldown on Starfall by 50%." }
entries[236616] = { ["name"] = "Soul of the Night", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Night:\n\nIncreases the damage done and damage radius of Starfall's stars and Hurricane by 25%." }
entries[236617] = { ["name"] = "Soul of the Keepers", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Keepers:\n\nYour Wrath casts have a 10% chance to summon a stand of 3 Treants to attack your target for 15 sec." }
entries[236618] = { ["name"] = "Soul of the Wrathful", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Wrathful:\n\nYour Wrath critical strikes have a 50% chance to make your next Starfire deal 10% increased damage, stacking up to 3 times." }
entries[236619] = { ["name"] = "Soul of the Graceful", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Graceful:\n\nYour Nature's Grace talent gains 1 additional charge each time it triggers." }
entries[236620] = { ["name"] = "Soul of the Astral Ascendant", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Astral Ascendant:\n\nIncreases the critical strike damage bonus of your Starfire, Starsurge, and Wrath by 60%." }
entries[236621] = { ["name"] = "Soul of the Cometcaller", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Cometcaller:\n\nReduces the cast time and global cooldown of Starfire by 0.5 sec." }
entries[236622] = { ["name"] = "Soul of the Forest", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of the Forest:\n\nIncreases the critical strike chance of Wrath by 10%." }
entries[236623] = { ["name"] = "Soul of Animalistic Expertise", ["text"] = "Binds when picked up\nUnique (20)\nClasses: Druid\nRequires Level 55\nUse: Permanently imbue your shoulders with the Soul of Animalistic Expertise:\n\nYour melee attacks have 5% less chance to be Dodged or Parried." }
