entries[236707] = { ["name"] = "Tunic of Undead Slaying", ["text"] = "Sanctified\nBinds when picked up\nChest Leather\n210 Armor\n+23 Stamina\nDurability 120 / 120\nRequires Level 58\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: +108 Attack Power when fighting Undead.\n\nUndead Slayer's Armor (0/3)\nTunic of Undead Slaying\nHandwraps of Undead Slaying\nWristwraps of Undead Slaying\n(2) Set : Treats your Seal of the Dawn bonus as if you were wearing 2 additional Sanctified items. (Equipping more than 8 Sanctified items provides no additional benefit)" }
