entries[238945] = { ["name"] = "Caladboulder", ["text"] = "Binds when picked up\nTwo-Hand Mace\n334 - 501 Damage Speed 4.30\n(97.09 damage per second)\n+30 Strength\n+10 Agility\n+5 Stamina\nDurability 300 / 300\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nChance on hit: The weight of Caladboulder knocks down all nearby enemies for 4 sec.\nEquip: Movement speed reduced by 10%.\n\"The Sword and the Stone\"" }
entries[238960] = { ["name"] = "Quartermaster's Crate", ["text"] = "Quest Item\nUse: Stash a piece of crafted Scarlet Crusade equipment in the crate. This will permanently destroy the item." }
entries[238961] = { ["name"] = "Caladbolg", ["text"] = "Binds when picked up\nTwo-Hand Sword\n339 - 509 Damage Speed 3.90\n(108.72 damage per second)\n+50 Strength\n+15 Agility\n+7 Stamina\nDurability 120 / 120\nRequires Level 60\nEquip: Increases your attack speed by 2%.\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nUse: The earth once again swallow up Caladbolg for 20 sec, decreasing movement speed by 50%. If moving, your speed increases every 2 seconds. Smashing into an enemy deals 300 to 2700 fire damage, knocks back all nearby enemy players, and ends this effect. (2 Min Cooldown)\n\"An ancient blade, kept in secret by the Scarlet Crusade. Slightly used.\"" }
entries[238985] = { ["name"] = "Heavy Crate", ["text"] = "Quest Item\n\"Deliver to the Scarlet Quartermaster to complete Prove Your Worth.\"" }
entries[239010] = { ["name"] = "Hilt of the Ashbringer", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n99 - 162 Damage Speed 2.00\n(65.25 damage per second)\nDurability 15 / 15\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nUse: Attempt to make contact with the Will of The Ashbringer. (4 Min Cooldown)" }
