entries[239060] = { ["name"] = "Will of the Mountain", ["text"] = "Will of the Mountain\nBinds when picked up\nMain Hand Mace\n169 - 316 Damage Speed 2.90\n(83.62 damage per second)\n+17 Strength\n+5 Stamina\nDurability 105 / 105\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nChance on hit: Invoke the Will of the Mountain, increasing physical damage dealt by 5%, armor by 500, and size by 20% for 15 sec.\n\"Once a mighty blacksmithing hammer, this truly stunning work of art is even more inspiring when you hold it.\"" }
