entries[239246] = { ["name"] = "Fizzlefuse's Shopping List", ["text"] = "Binds when picked up\nUnique\n\"A list of items hastily scribbled down whenever it crossed the author's mind.\"\n<Right Click to Read>" }
entries[239248] = { ["name"] = "Scarlet Junkbox", ["text"] = "Binds when picked up\n\"Contains whatever spare junk was laying around, and sometimes something valuable from a foolhardy adventurer.\"\n<Right Click to Open>" }
entries[239292] = { ["name"] = "Forgewright's Notes", ["text"] = "Quest Item\nUnique\n\"Contains the collected thoughts and works of Franclorn Forgewright.\"" }
entries[239301] = { ["name"] = "Corrupted Ashbringer", ["text"] = "Sanctified\nBinds when picked up\nUnique\nTwo-Hand Sword\n357 - 536 Damage Speed 3.80\n(117.50 damage per second)\n+53 Strength\n-30 Stamina\nDurability 145 / 145\nRequires Level 60\nEquip: Inflicts the will of the Ashbringer upon the wielder.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 3%.\nEquip: Reduces the chance for your attacks to be dodged or parried by 2%.\nChance on hit: Steals 475 to 525 life from up to 5 enemies, granting 30 Strength or Agility per enemy siphoned, stacking up to 5 times.\n\"Blade of the Scarlet Highlord\"" }
entries[239302] = { ["name"] = "Scarlet Uniform Belt", ["text"] = "Quest Item\n\"A dense leather strap with a heavy steel buckle. Truly a masterpiece of a belt, ready to be ruined by reckless tinkering.\"" }
entries[239316] = { ["name"] = "Triangulation Samophlange", ["text"] = "Quest Item\nRequires Engineering (1)\nUse: Use the device at a designated triangulation point to aid Fizzlefuse in his teleporter's calibration. (10 Sec Cooldown)" }
entries[239512] = { ["name"] = "Lightbreaker Wrists", ["text"] = "Sanctified\nBinds when picked up\nWrist Plate\n477 Armor\n+29 Strength\n+10 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Warrior\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases your attack speed by 1%.\n\nLightbreaker's Warplate (0/8)\nLightbreaker Greathelm\nLightbreaker Shoulders\nLightbreaker Cuirass\nLightbreaker Belt\nLightbreaker Tassets\nLightbreaker Greaves\nLightbreaker Wrists\nLightbreaker Grips\n(2) Set : Your Heroic Strike, Cleave, and Quick Strike damage is increased by 20% while in Battle Stance or Berserker Stance. Your Cleave strikes 1 additional target and can trigger Blood Surge.\n(4) Set : Each time you hit a target with Whirlwind, Heroic Strike, Quick Strike, or Cleave, the damage of your next Slam is increased by 20%, stacking up to 5 times.\n(6) Set : Each time Deep Wounds deals damage, it reduces the remaining cooldown on your Whirlwind by 3 sec. Whirlwind deals 100% increased damage to targets afflicted with your Deep Wounds." }
