entries[239529] = { ["name"] = "Dawnstalker Breastplate", ["text"] = "Sanctified\nBinds when picked up\nChest Mail\n611 Armor\n+49 Agility\n+20 Stamina\nDurability 140 / 140\nClasses: Hunter\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases your attack speed by 2%.\nEquip: +50 Attack Power.\n\nDawnstalker Prowess (0/8)\nDawnstalker Visor\nDawnstalker Pauldrons\nDawnstalker Breastplate\nDawnstalker Belt\nDawnstalker Leggings\nDawnstalker Greaves\nDawnstalker Vambraces\nDawnstalker Gauntlets\n(2) Set : Your Strikes and Mongoose Bite deal 25% increased damage to targets afflicted with your Serpent Sting or Wyvern Strike.\n(4) Set : Your melee critical strikes increase your attack speed by 30% for 10 sec.\n(6) Set : Increases the bonus damage from Raptor Fury by an additional 15% per stack." }
