entries[239562] = { ["name"] = "Duskwraith Breastplate", ["text"] = "Sanctified\nBinds when picked up\nChest Leather\n275 Armor\n+32 Strength\n+49 Agility\n+17 Stamina\nDurability 120 / 120\nClasses: Rogue\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases your attack speed by 1%.\n\nDuskwraith Armor (0/8)\nDuskwraith Helmet\nDuskwraith Pauldrons\nDuskwraith Breastplate\nDuskwraith Waistguard\nDuskwraith Legplates\nDuskwraith Sabatons\nDuskwraith Bracers\nDuskwraith Gauntlets\n(2) Set : While Just a Flesh Wound is not active, your Backstab, Sinister Strike, Saber Slash, and Mutilate deal 20% increased damage per your active Poison or Bleed effect afflicting the target, up to a maximum increase of 60%.\n(4) Set : Your Poison and autoattack critical strikes have a 10% chance to grant you a combo point. (Proc chance: 10%)\n(6) Set : Increases Ambush, Eviscerate, Crimson Tempest, and Envenom damage by 50%." }
entries[239565] = { ["name"] = "Garb of Revelation", ["text"] = "Sanctified\nBinds when picked up\nChest Cloth\n146 Armor\n+15 Stamina\n+17 Intellect\nDurability 100 / 100\nClasses: Priest\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases the damage dealt by your damage over time spells by 2%.\nEquip: Increases damage done by Shadow spells and effects by up to 76.\n\nRaiments of Revelation (0/8)\nCrown of Revelation\nMantle of Revelation\nGirdle of Revelation\nPants of Revelation\nBoots of Revelation\nWrists of Revelation\nHands of Revelation\nGarb of Revelation\n(2) Set : Your Mind Flay and Mind Sear no longer lose duration from taking damage during their channel. In addition, they deal 10% increased damage per other periodic Shadow effect you have on the target, up to a maximum increase of 30%.\n(4) Set : Your Mind Blast deals 50% reduced threat, and gains 20% damage increase from each stack of Mind Spike on the target.\n(6) Set : Damage done by your Mind Flay now increases the longer you channel the spell. Each time it deals damage, subsequent damage will increase by 70%. This resets on each new channel." }
