entries[239694] = { ["name"] = "Covenant of Light", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 60\nSummon Climhazzard, Mount of the High Commander. Speed is increased by 100%.\n\"Learn to summon and dismiss Climhazzard, Mount of the High General. This is a very fast mount.\"" }
