entries[240020] = { ["name"] = "Inquisition Legguards", ["text"] = "Sanctified\nBinds when picked up\nLegs Plate\n954 Armor\n+17 Stamina\n+24 Intellect\nDurability 120 / 120\nClasses: Paladin\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 3%.\nEquip: Increases your casting speed by 1%.\nEquip: Increases healing done by up to 99 and damage done by up to 33 for all magical spells and effects.\n\nInquisition Armor (0/8)\nInquisition Headpiece\nInquisition Spaulders\nInquisition Tunic\nInquisition Girdle\nInquisition Legguards\nInquisition Boots\nInquisition Wristguards\nInquisition Handguards\n(2) Set : Lay on Hands grants you 20% Spell Haste for 30 sec and reduces the Global Cooldown of your next 5 Divine Light, Holy Light, Flash of Light, or Holy Shock spells by 0.5 seconds.\n(4) Set : Your Beacon of Light now also triggers when you heal your Beacon of Light target, but at 50% reduced effectiveness.\n(6) Set : An additional 25% of your healing is transferred to your Beacon of Light target." }
entries[240021] = { ["name"] = "Inquisition Spaulders", ["text"] = "Sanctified\nBinds when picked up\nShoulder Plate\n818 Armor\n+13 Stamina\n+14 Intellect\nDurability 100 / 100\nClasses: Paladin\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 2%.\nEquip: Increases your casting speed by 2%.\nEquip: Increases healing done by up to 64 and damage done by up to 22 for all magical spells and effects.\n\nInquisition Armor (0/8)\nInquisition Headpiece\nInquisition Spaulders\nInquisition Tunic\nInquisition Girdle\nInquisition Legguards\nInquisition Boots\nInquisition Wristguards\nInquisition Handguards\n(2) Set : Lay on Hands grants you 20% Spell Haste for 30 sec and reduces the Global Cooldown of your next 5 Divine Light, Holy Light, Flash of Light, or Holy Shock spells by 0.5 seconds.\n(4) Set : Your Beacon of Light now also triggers when you heal your Beacon of Light target, but at 50% reduced effectiveness.\n(6) Set : An additional 25% of your healing is transferred to your Beacon of Light target." }
entries[240022] = { ["name"] = "Inquisition Boots", ["text"] = "Sanctified\nBinds when picked up\nFeet Plate\n749 Armor\n+13 Stamina\n+15 Intellect\nDurability 75 / 75\nClasses: Paladin\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases your casting speed by 2%.\nEquip: Increases healing done by up to 68 and damage done by up to 23 for all magical spells and effects.\n\nInquisition Armor (0/8)\nInquisition Headpiece\nInquisition Spaulders\nInquisition Tunic\nInquisition Girdle\nInquisition Legguards\nInquisition Boots\nInquisition Wristguards\nInquisition Handguards\n(2) Set : Lay on Hands grants you 20% Spell Haste for 30 sec and reduces the Global Cooldown of your next 5 Divine Light, Holy Light, Flash of Light, or Holy Shock spells by 0.5 seconds.\n(4) Set : Your Beacon of Light now also triggers when you heal your Beacon of Light target, but at 50% reduced effectiveness.\n(6) Set : An additional 25% of your healing is transferred to your Beacon of Light target." }
entries[240023] = { ["name"] = "Inquisition Vambraces", ["text"] = "Sanctified\nBinds when picked up\nWrist Plate\n477 Armor\n+29 Strength\n+10 Agility\n+13 Stamina\nDurability 55 / 55\nClasses: Paladin\nRequires Level 60\nEquip: Reduces the chance for your attacks to be dodged or parried by 1%.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\n\nInquisition Warplate (0/8)\nInquisition Helmet\nInquisition Shoulderplates\nInquisition Breastplate\nInquisition Belt\nInquisition Leggings\nInquisition Greaves\nInquisition Vambraces\nInquisition Gloves\n(2) Set : While you have a two-handed weapon equipped, Crusader Strike and Exorcism grant you Holy Power, increasing all Holy damage you deal by 10%, stacking up to 3 times. (100ms cooldown)\n(4) Set : Divine Storm, Holy Shock, and Holy Wrath consume all your Holy Power, dealing 100% increased damage per Holy Power you have accumulated, 50% effective against player controlled targets.\n(6) Set : Consuming Holy Power increases your Attack Power by 15% per Holy Power consumed for 10 sec." }
