entries[240852] = { ["name"] = "Crimson Cleaver", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Axe\n169 - 316 Damage Speed 2.90\n(83.62 damage per second)\n+16 Strength\nDurability 105 / 105\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: The Crimson Cleaver does not respond to your presence, maybe another class could benefit from this?\n\nHack and Smash (0/2)\nMercy\nCrimson Cleaver\n(2) Set : The damage increases from Mercy's and Crimson Cleaver's effects are increased by 10%." }
entries[240853] = { ["name"] = "Queensfall", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Dagger\n123 - 229 Damage Speed 2.10\n(83.81 damage per second)\n+19 Agility\nDurability 75 / 75\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: [ S03 - Tuning and Overrides Passive - Warrior : Your Bloodthirst, Mortal Strike, Shield Slam, Heroic Strike, and Cleave critical strikes set the duration of your Rend on the target to 21 sec ] [ Rogue Passive (DND) : Your Backstab, Mutilate, and Saber Slash critical strikes set the duration of your Rupture on the target to 16 sec and your Crimson Tempest to 12 sec ] [ S03 - Tuning and Overrides Passive - Hunter : Your Raptor Strike and Mongoose Bite critical strikes set the duration of your Serpent Sting on the target to 15 sec / You will never be worthy enough to benefit from this blade ].\n\nFallen Regality (0/2)\nKingsfall\nQueensfall\n(2) Set : The blades will never accept you as their master." }
