entries[240998] = { ["name"] = "Soporific Blade", ["text"] = "Binds when picked up\nMain Hand Dagger\n33 - 134 Damage Speed 2.00\n(41.75 damage per second)\n+11 Stamina\n+10 Intellect\nDurability 75 / 75\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 169.\nUse: Your next regular melee attack made within 20 sec deals Arcane damage equal to 2 times your spell power, and puts the target to sleep for 20 sec. (2 Min Cooldown)" }
entries[241001] = { ["name"] = "Tyr's Fall", ["text"] = "Binds when picked up\nMain Hand Mace\n39 - 160 Damage Speed 2.40\n(41.46 damage per second)\n+9 Stamina\n+17 Intellect\nDurability 105 / 105\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases damage and healing done by magical spells and effects by up to 169.\nEquip: Dealing periodic damage has a 5% chance to grant 120 spell damage and healing for 15 sec. (Proc chance: 5%)" }
entries[241002] = { ["name"] = "Remnants of the Red", ["text"] = "Binds when picked up\nMain Hand Sword\n39 - 160 Damage Speed 2.40\n(41.46 damage per second)\n+5 Stamina\n+10 Intellect\nDurability 105 / 105\nRequires Level 60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increases your casting speed by 2%.\nEquip: Increases damage and healing done by magical spells and effects by up to 169.\nEquip: Dealing non-periodic Fire damage has a 5% chance to increase your Fire damage dealt by 5% for 15 sec. (Proc chance: 5%)" }
entries[241003] = { ["name"] = "Mirage, Rod of Illusion", ["text"] = "Binds when picked up\nTwo-Hand Staff\n200 - 279 Damage Speed 3.60\n(66.53 damage per second)\n+12 Stamina\n+28 Intellect\nDurability 120 / 120\nRequires Level 60\nEquip: Increases your casting speed by 2%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 3%.\nEquip: Increases damage and healing done by magical spells and effects by up to 169.\nEquip: Chance on landing a damaging spell to create a Mirage on top of your target that deals arcane damage to nearby enemies for 30 sec. (Proc chance: 10%, 30s cooldown)\nUse: Swap places with your Mirage. (2 Min Cooldown)" }
entries[241004] = { ["name"] = "Conundrum", ["text"] = "Binds when picked up\nRanged Wand\n159 - 296 Holy Damage Speed 1.50\n(151.67 damage per second)\n-10 Stamina\nDurability 75 / 75\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\nEquip: The range of your Mind Flay, Fire Blast, and Drain Life spells is increased by 10 yards, but Mind Flay no longer slows enemies." }
entries[241006] = { ["name"] = "Spire of Sacrifice", ["text"] = "Binds when picked up\nMain Hand Mace\n39 - 160 Damage Speed 2.40\n(41.46 damage per second)\n+7 Stamina\nDurability 105 / 105\nRequires Level 60\nEquip: Increases your casting speed by 2%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases healing done by up to 317 and damage done by up to 106 for all magical spells and effects.\nUse: While above 30% health, your healing is increased by 200, but your heals will cause you to sacrifice 5% of your total health every cast. While under this effect you may only receive healing from directly targeted, non-periodic heals. (Toggled Effect) (10 Sec Cooldown)" }
entries[241008] = { ["name"] = "Condemnation", ["text"] = "Binds when picked up\nTwo-Hand Staff\n187 - 263 Damage Speed 3.60\n(62.50 damage per second)\n+20 Stamina\n+30 Intellect\n+21 Spirit\nDurability 120 / 120\nRequires Level 60\nEquip: Improves your chance to get a critical strike with all spells and attacks by 3%.\nEquip: Increases healing done by up to 317 and damage done by up to 106 for all magical spells and effects.\nEquip: Damaging spell casts on enemies Condemns them for 20 sec. Whenever they deal damage, their target is healed for 3% of their maximum health. Lasts 20 sec or up to 10 hits. (60 Secs Cooldown) (1m cooldown)" }
entries[241011] = { ["name"] = "Greatstaff of Fealty", ["text"] = "Binds when picked up\nTwo-Hand Staff\n200 - 279 Damage Speed 3.60\n(66.53 damage per second)\n+16 Stamina\n+20 Intellect\n+30 Spirit\nDurability 120 / 120\nRequires Level 60\nEquip: Increases your casting speed by 4%.\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nEquip: Increases healing done by up to 317 and damage done by up to 106 for all magical spells and effects.\nEquip: If there are no enemies within 20 yards of you, heal all party members within 20 yards for 125 every 3 seconds. A party may only swear Fealty to one player at a time." }
