entries[241191] = { ["name"] = "Formula: Enchant Weapon - Grand Crusader", ["text"] = "Binds when picked up\nRequires Enchanting (280)\nPermanently enchant a melee weapon so that often when attacking in melee it heals for 350 to 450 and increases Strength by 120 for 20 sec.\n\"Teaches you how to permanently enchant a weapon to occasionally bless the wielder with incredible strength.\"" }
