entries[242267] = { ["name"] = "From Arcanist to Archmage", ["text"] = "Binds when picked up\n\"A self-promoting autobiography written by an author too irrelevant to be named. Interestingly, the book also thrums with an attention seeking spell.\"" }
entries[242268] = { ["name"] = "If You Give a Crusader an Enchant", ["text"] = "Binds when picked up\n\"An entertaining short story that quickly descends into madness before culminating in giving the antagonist everything he wants. Amusingly, the book shimmers with power.\"" }
